/// <summary>
/// MPJ_17989 - kscerri - 12/14/2021
/// Class <c>METCustTransListingDP</c> data provider
/// </summary>
[
    SRSReportParameterAttribute(classstr(METCustAuditReportContract))
]
class METCustAuditReportDP extends SRSReportDataProviderBase
{
    // Contains payment data
    METCustAuditReportTmp       custAuditReportTmp;
    METCustAuditReportContract  contract;
    Query                       queryCustTable, queryMetCustTable, queryLogisticsElectronicAddr, 
                                queryDirPartyTable, queryLogisticsLocation, queryLogisticsPostalAddr;
    
}

