    /// <summary>
    /// MPJ_3863 - kscerri - 06/08/2021
    /// processes data
    /// </summary>
    /// <param name = "_query">query</param>
    public void processData(Query _query)
    {
        QueryRun                    queryRun;
        CustTable                   custTable;
        METCustTable                metCustTable;
        LogisticsElectronicAddress  logisticsElectronicAddress;
        SysDataBaseLog              sysDataBaseLog;
        LogisticsLocation           logisticsLocation;
        List                        list = new List(Types::Container);
        ListEnumerator              listEnumerator;
        container                   change;
        System.String               fieldString;
        System.Object               newValue;
        System.Object               oldValue;

        if (_query)
        {
            queryRun = new QueryRun(_query);
            
            if(!queryRun.next())
            {
                return;
            }

            do
            {
                try
                {
                    custTable       = queryRun.get(tableNum(CustTable));
                }
                catch
                {
                }
                try
                {
                    metCustTable    = queryRun.get(tableNum(metCustTable));
                }
                catch
                {
                }
                try
                {
                    sysDataBaseLog  = queryRun.get(tableNum(SysDataBaseLog));
                }
                catch
                {
                }
                try
                {
                    logisticsElectronicAddress  = queryRun.get(tableNum(LogisticsElectronicAddress));
                }
                catch
                {
                }
                try
                {
                    logisticsLocation  = queryRun.get(tableNum(LogisticsLocation));
                }
                catch
                {
                }
                
                list            = sysDataBaseLog.getDataAslist();
                listEnumerator  =  list.getEnumerator();
                while (listEnumerator.moveNext())
                {
                    change = listEnumerator.current();
                    [fieldString, newValue, oldValue] = change;

                    if (fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(CustTable, ModifiedDateTime) &&
                        fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(CustTable, ModifiedBy) &&
                        fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(LogisticsElectronicAddress, ChannelReferenceId) &&
                        fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(LogisticsElectronicAddress, SysRowVersionNumber))

                    {
                        ttsbegin;

                        if (custTable)
                        {
                            custAuditReportTmp.AccountNum           = custTable.AccountNum;
                            custAuditReportTmp.CustName             = dirPartyTable::findRec(custTable::find(custTable.AccountNum).party).Name;
                            custAuditReportTmp.LegalEntity          = custTable.DataAreaId;
                        }
                        else if(metCustTable)
                        {
                            custAuditReportTmp.AccountNum           = metCustTable.AccountNum;
                            custAuditReportTmp.CustName             = dirPartyTable::findRec(custTable::find(metCustTable.AccountNum).party).Name;
                            custAuditReportTmp.LegalEntity          = metCustTable.DataAreaId;
                        }
                        custAuditReportTmp.DateOfChange         = sysDataBaseLog.CreatedDateTime;
                        
                        custAuditReportTmp.NewChange            = METNewChange::Change;
                        custAuditReportTmp.TableName            = tableId2Name(sysDataBaseLog.table);
                        custAuditReportTmp.UserIdCreatedBy      = sysDataBaseLog.CreatedBy;
                        custAuditReportTmp.Field                = fieldId2Name(sysDataBaseLog.table, str2int(fieldString));
                        custAuditReportTmp.LogRecId             = sysDataBaseLog.LogRecId;

                        DictField   dictField = new DictField(sysDataBaseLog.table,
                                                            fieldName2Id(sysDataBaseLog.table, custAuditReportTmp.Field));
                                
                        switch  (custAuditReportTmp.TableName)
                        {
                            case tableStr(LogisticsElectronicAddress):
                                custAuditReportTmp.FieldLabel = strFmt("%1 %2", logisticsElectronicAddress.ElectronicAddressRoles,
                                enum2Str(logisticsElectronicAddress.Type));
                                break;
                            case tableStr(LogisticsLocation):
                                
                                custAuditReportTmp.FieldLabel = DirPartyLocation::findByPartyLocation(custTable.Party, sysDataBaseLog.LogRecId).locationRoleNames();
                                
                                if (dictField)
                                {
                                    if(custAuditReportTmp.FieldLabel)
                                    {
                                        custAuditReportTmp.FieldLabel       = strFmt("%1 %2", custAuditReportTmp.FieldLabel, dictField.label());
                                    }
                                    else
                                    {
                                        custAuditReportTmp.FieldLabel       = dictField.label();
                                    }
                                }
                                break;
                            default:
                                if (dictField)
                                {
                                    custAuditReportTmp.FieldLabel       = dictField.label();
                                }
                                break;
                        }
                        
                        custAuditReportTmp.NewValue             = newValue;
                        custAuditReportTmp.OldValue             = oldValue;
                        custAuditReportTmp.insert();
                        ttscommit;
                    }
                }
            }
            while (queryRun.next());
        }
    }
